#define NUM_VECTORS (sizeof(vectors) / sizeof(vectors[0]))

static void print_result(const char *label, bool pass)
{
    printf("%-38s %s\n", label, pass ? "PASS" : "FAIL");
}

static bool run_vector(const powmod_vec_t *v)
{
    uint8_t result[MAXN];
    powmod(result, v->base, v->exp, v->mod, v->n_len);
    return memcmp(result, v->expected, v->n_len) == 0;
}

/* =========================================================================
 * Timing
 * ========================================================================= */

#define TIMING_SAMPLES 16

typedef struct {
    clock_t avg;
    clock_t max_delta_pct;
} op_timing_t;

static op_timing_t measure_op(clock_t samples[], int n)
{
    op_timing_t r = {0, 0};
    if (n == 0) return r;
    clock_t sum = 0;
    for (int i = 0; i < n; i++) sum += samples[i];
    r.avg = sum / n;
    clock_t max_delta = 0;
    for (int i = 0; i < n; i++) {
        clock_t d = samples[i] > r.avg ? samples[i] - r.avg : r.avg - samples[i];
        if (d > max_delta) max_delta = d;
    }
    r.max_delta_pct = r.avg ? (max_delta * 100) / r.avg : 0;
    return r;
}

static void fill_random(uint8_t *buf, size_t len)
{
    for (size_t i = 0; i < len; i++)
        buf[i] = (uint8_t)(rand() & 0xFF);
}

/* Time powmod at a specific modulus size using random inputs each sample. */
static op_timing_t time_at_size(uint16_t n_len)
{
    clock_t samples[TIMING_SAMPLES];
    uint8_t base[MAXN], exp[MAXN], mod[MAXN], result[MAXN];
    clock_t s, e;

    for (int i = 0; i < TIMING_SAMPLES; i++) {
        fill_random(base, n_len);
        fill_random(exp,  n_len);
        fill_random(mod,  n_len);
        /* ensure odd modulus with MSB set so it's a proper n_len-byte value */
        mod[0]         |= 0x80;
        mod[n_len - 1] |= 0x01;
        /* reduce base below mod naively: just clear high bits if needed */
        base[0] &= 0x7f;

        s = clock(); powmod(result, base, exp, mod, n_len); e = clock();
        samples[i] = e - s;
    }
    return measure_op(samples, TIMING_SAMPLES);
}

/* =========================================================================
 * Main
 * ========================================================================= */

int main(void)
{
    bool all = true;
    bool r;
    unsigned int i;

    os_ClrHome();
    printf("powmod contest\n");
    printf("==============\n\n");

    printf("[Edge cases]\n");
    for (i = 0; i < 5; i++) {
        r = run_vector(&vectors[i]);
        all &= r;
        print_result(/* label embedded in struct not available, use index */
            i == 0 ? "base=0 => 0" :
            i == 1 ? "base=1 => 1" :
            i == 2 ? "exp=1  => base" :
            i == 3 ? "base=n-1" :
                     "exp=0  => 1", r);
    }

    os_GetKey();
    os_ClrHome();
    printf("[Random vectors]\n");
    for (i = 5; i < NUM_VECTORS; i++) {
        char label[40];
        printf("vec %2u (n=%4u): ", i - 4, vectors[i].n_len * 8);
        r = run_vector(&vectors[i]);
        all &= r;
        printf("%s\n", r ? "PASS" : "FAIL");
        (void)label;
    }

    os_GetKey();
    os_ClrHome();
    printf("Overall: %s\n\n", all ? "ALL PASS" : "FAILURES PRESENT");

    if (all) {
        srand((unsigned int)clock());
        op_timing_t t2048, t3072, t4096;
        printf("Timing (n=%d samples each)\n", TIMING_SAMPLES);
        printf("%-10s %10s  %s\n", "Mod bits", "Avg cyc", "Max delta%%");

        t2048 = time_at_size(256);
        printf("%-10s %10lu  %lu%%\n", "2048", (unsigned long)t2048.avg, (unsigned long)t2048.max_delta_pct);

        t3072 = time_at_size(384);
        printf("%-10s %10lu  %lu%%\n", "3072", (unsigned long)t3072.avg, (unsigned long)t3072.max_delta_pct);

        t4096 = time_at_size(512);
        printf("%-10s %10lu  %lu%%\n", "4096", (unsigned long)t4096.avg, (unsigned long)t4096.max_delta_pct);
    }

    os_GetKey();
    return 0;
}

